    // repeat replaces the top stack element with itself repeated according to op, min, max.
    // before is the regexp suffix starting at the repetition operator.
    // after is the regexp suffix following after the repetition operator.
    // repeat returns an updated 'after' and an error, if any.
    std::tuple<gocpp::string, gocpp::error> rec::repeat(parser* p, Op op, int min, int max, gocpp::string before, gocpp::string after, gocpp::string lastRepeat)
    {
        auto flags = p->flags;
        if(p->flags & PerlX != 0)
        {
            if(len(after) > 0 && after[0] == '?')
            {
                after = after.make_slice(1);
                flags ^= NonGreedy;
            }
            if(lastRepeat != ""_s)
            {
                // In Perl it is not allowed to stack repetition operators:
                // a** is a syntax error, not a doubled star, and a++ means
                // something else entirely, which we don't support!
                return {""_s, gocpp::error(new golang::syntax::Error {ErrInvalidRepeatOp, lastRepeat.make_slice(0, len(lastRepeat) - len(after))})};
            }
        }
        auto n = len(p->stack);
        if(n == 0)
        {
            return {""_s, gocpp::error(new golang::syntax::Error {ErrMissingRepeatArgument, before.make_slice(0, len(before) - len(after))})};
        }
        auto sub = p->stack[n - 1];
        if(sub->Op >= opPseudo)
        {
            return {""_s, gocpp::error(new golang::syntax::Error {ErrMissingRepeatArgument, before.make_slice(0, len(before) - len(after))})};
        }

        auto re = rec::newRegexp(gocpp::recv(p), op);
        re->Min = min;
        re->Max = max;
        re->Flags = flags;
        re->Sub = re->Sub0.make_slice(0, 1);
        re->Sub[0] = sub;
        p->stack[n - 1] = re;
        rec::checkLimits(gocpp::recv(p), re);

        if(op == OpRepeat && (min >= 2 || max >= 2) && ! repeatIsValid(re, 1000))
        {
            return {""_s, gocpp::error(new golang::syntax::Error {ErrInvalidRepeatSize, before.make_slice(0, len(before) - len(after))})};
        }

        return {after, nullptr};
    }

    // repeatIsValid reports whether the repetition re is valid.
    // Valid means that the combination of the top-level repetition
    // and any inner repetitions does not exceed n copies of the
    // innermost thing.
    // This function rewalks the regexp tree and is called for every repetition,
    // so we have to worry about inducing quadratic behavior in the parser.
    // We avoid this by only calling repeatIsValid when min or max >= 2.
    // In that case the depth of any >= 2 nesting can only get to 9 without
    // triggering a parse error, so each subtree can only be rewalked 9 times.
    bool repeatIsValid(Regexp* re, int n)
    {
        if(re->Op == OpRepeat)
        {
            auto m = re->Max;
            if(m == 0)
            {
                return true;
            }
            if(m < 0)
            {
                m = re->Min;
            }
            if(m > n)
            {
                return false;
            }
            if(m > 0)
            {
                n /= m;
            }
        }
        for(auto [gocpp_ignored, sub] : re->Sub)
        {
            if(! repeatIsValid(sub, n))
            {
                return false;
            }
        }
        return true;
    }

    // concat replaces the top of the stack (above the topmost '|' or '(') with its concatenation.
    Regexp* rec::concat(parser* p)
    {
        rec::maybeConcat(gocpp::recv(p), - 1, 0);

        // Scan down to find pseudo-operator | or (.
        auto i = len(p->stack);
        for(; i > 0 && p->stack[i - 1]->Op < opPseudo; )
        {
            i--;
        }
        auto subs = p->stack.make_slice(i);
        p->stack = p->stack.make_slice(0, i);

        // Empty concatenation is special case.
        if(len(subs) == 0)
        {
            return rec::push(gocpp::recv(p), rec::newRegexp(gocpp::recv(p), OpEmptyMatch));
        }

        return rec::push(gocpp::recv(p), rec::collapse(gocpp::recv(p), subs, OpConcat));
    }

    // alternate replaces the top of the stack (above the topmost '(') with its alternation.
    Regexp* rec::alternate(parser* p)
    {
        // Scan down to find pseudo-operator (.
        // There are no | above (.
        auto i = len(p->stack);
        for(; i > 0 && p->stack[i - 1]->Op < opPseudo; )
        {
            i--;
        }
        auto subs = p->stack.make_slice(i);
        p->stack = p->stack.make_slice(0, i);

        // Make sure top class is clean.
        // All the others already are (see swapVerticalBar).
        if(len(subs) > 0)
        {
            cleanAlt(subs[len(subs) - 1]);
        }

        // Empty alternate is special case
        // (shouldn't happen but easy to handle).
        if(len(subs) == 0)
        {
            return rec::push(gocpp::recv(p), rec::newRegexp(gocpp::recv(p), OpNoMatch));
        }

        return rec::push(gocpp::recv(p), rec::collapse(gocpp::recv(p), subs, OpAlternate));
    }

    // cleanAlt cleans re for eventual inclusion in an alternation.
    void cleanAlt(Regexp* re)
    {
        //Go switch emulation
        {
            auto condition = re->Op;
            int conditionId = -1;
            if(condition == OpCharClass) { conditionId = 0; }
            switch(conditionId)
            {
                case 0:
                    re->Rune = cleanClass(& re->Rune);
                    if(len(re->Rune) == 2 && re->Rune[0] == 0 && re->Rune[1] == unicode::MaxRune)
                    {
                        re->Rune = nullptr;
                        re->Op = OpAnyChar;
                        return;
                    }
                    if(len(re->Rune) == 4 && re->Rune[0] == 0 && re->Rune[1] == '\n' - 1 && re->Rune[2] == '\n' + 1 && re->Rune[3] == unicode::MaxRune)
                    {
                        re->Rune = nullptr;
                        re->Op = OpAnyCharNotNL;
                        return;
                    }
                    if(cap(re->Rune) - len(re->Rune) > 100)
                    {
                        // re.Rune will not grow any more.
                        // Make a copy or inline to reclaim storage.
                        re->Rune = append(re->Rune0.make_slice(0, 0), re->Rune);
                    }
                    break;
            }
        }
    }

    // collapse returns the result of applying op to sub.
    // If sub contains op nodes, they all get hoisted up
    // so that there is never a concat of a concat or an
    // alternate of an alternate.
    Regexp* rec::collapse(parser* p, gocpp::slice<Regexp*> subs, Op op)
    {
        if(len(subs) == 1)
        {
            return subs[0];
        }
        auto re = rec::newRegexp(gocpp::recv(p), op);
        re->Sub = re->Sub0.make_slice(0, 0);
        for(auto [gocpp_ignored, sub] : subs)
        {
            if(sub->Op == op)
            {
                re->Sub = append(re->Sub, sub->Sub);
                rec::reuse(gocpp::recv(p), sub);
            }
            else
            {
                re->Sub = append(re->Sub, sub);
            }
        }
        if(op == OpAlternate)
        {
            re->Sub = rec::factor(gocpp::recv(p), re->Sub);
            if(len(re->Sub) == 1)
            {
                auto old = re;
                re = re->Sub[0];
                rec::reuse(gocpp::recv(p), old);
            }
        }
        return re;
    }

    // factor factors common prefixes from the alternation list sub.
    // It returns a replacement list that reuses the same storage and
    // frees (passes to p.reuse) any removed *Regexps.
